import { expect, sample, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

const cases = [
  { label: "an empty file", kind: "w9", name: "w9.txt", mimeType: "text/plain", size: 0, status: 422, code: "empty_file" },
  { label: "a file of exactly 10 MiB + 1", kind: "w9", name: "w9.txt", mimeType: "text/plain", size: TEN_MIB + 1, status: 413, code: "file_too_large" },
  { label: "a .exe file", kind: "w9", name: "tool.exe", mimeType: "application/octet-stream", size: 2, status: 415, code: "unsupported_type" },
  { label: "a valid text file with an unknown kind", kind: "passport", name: "w9.txt", mimeType: "text/plain", size: 4, status: 422, code: "validation_error" },
] as const;

for (const c of cases) {
  test(`rejects ${c.label} as kind "${c.kind}" with ${c.status} ${c.code}`, { tag: "@DOC-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.com`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: c.kind,
        file: {
          name: c.name,
          mimeType: c.mimeType,
          buffer: Buffer.alloc(c.size, "a"),
        },
      },
    });

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(c.status);
    expect(JSON.parse(body).error?.code, body).toBe(c.code);
  });
}
